frappe.ui.form.on('Item', {
    refresh: function(frm) {
        // Trigger the logic on form load
        frm.trigger('is_fixed_asset');
    },
    is_fixed_asset: function(frm) {
        // Check if 'Is Fixed Asset' is checked
        if (frm.doc.is_fixed_asset) {
            // Hide 'Item Group' and make it optional
            frm.set_df_property('item_group', 'reqd', 0);
            frm.set_df_property('item_group', 'hidden', 1);
        } else {
            // Revert to default (Visible and Required) when unchecked
            frm.set_df_property('item_group', 'reqd', 1);
            frm.set_df_property('item_group', 'hidden', 0);
        }
        
        // Refresh the field to apply UI changes
        frm.refresh_field('item_group');
    }
});

