frappe.ui.form.on("Asset Movement", {
    setup: (frm) => {
        frm.set_query("to_employee", "assets", (doc) => {
            return {
                filters: {
                    company: doc.company,
                },
            };
        });
        frm.set_query("from_employee", "assets", (doc) => {
            return {
                filters: {
                    company: doc.company,
                },
            };
        });
        frm.set_query("reference_name", (doc) => {
            return {
                filters: {
                    company: doc.company,
                    docstatus: 1,
                },
            };
        });
        frm.set_query("reference_doctype", () => {
            return {
                filters: {
                    name: ["in", ["Purchase Receipt", "Purchase Invoice"]],
                },
            };
        });
        frm.set_query("asset", "assets", () => {
            return {
                filters: {
                    status: ["not in", ["Draft"]],
                },
            };
        });
    },

    onload: (frm) => {
        frm.trigger("set_required_fields");
    },

    purpose: (frm) => {
        // Clear child table 'to_employee' fields immediately if switching to Return
        if (frm.doc.purpose === "Return" && frm.doc.assets) {
            frm.doc.assets.forEach(row => {
                frappe.model.set_value(row.doctype, row.name, "to_employee", "");
            });
        }
        frm.trigger("set_required_fields");
    },

    set_required_fields: (frm, cdt, cdn) => {
        let fieldnames_to_be_altered;
        if (frm.doc.purpose === "Transfer") {
            fieldnames_to_be_altered = {
                target_location: { read_only: 0, reqd: 1 },
                source_location: { read_only: 1, reqd: 1 },
                from_employee: { read_only: 1, reqd: 0 },
                to_employee: { read_only: 1, reqd: 0 },
            };
        } else if (frm.doc.purpose === "Receipt") {
            fieldnames_to_be_altered = {
                target_location: { read_only: 0, reqd: 1 },
                source_location: { read_only: 1, reqd: 0 },
                from_employee: { read_only: 1, reqd: 0 },
                to_employee: { read_only: 0, reqd: 0 },
            };
        } else if (frm.doc.purpose === "Issue") {
            fieldnames_to_be_altered = {
                target_location: { read_only: 1, reqd: 0 },
                source_location: { read_only: 1, reqd: 0 },
                from_employee: { read_only: 1, reqd: 0 },
                to_employee: { read_only: 0, reqd: 1 },
            };
        } else if (frm.doc.purpose === "Transfer and Issue") {
            fieldnames_to_be_altered = {
                target_location: { read_only: 0, reqd: 1 },
                source_location: { read_only: 0, reqd: 1 },
                from_employee: { read_only: 0, reqd: 1 },
                to_employee: { read_only: 0, reqd: 1 },
            };
        } else if (frm.doc.purpose === "Return") {
            // New injection matching your requirements
            fieldnames_to_be_altered = {
                target_location: { read_only: 0, reqd: 1 }, // Asset comes back to a storage unit/location
                source_location: { read_only: 1, reqd: 0 },
                from_employee: { read_only: 0, reqd: 1 },   // Mandatory
                to_employee: { read_only: 1, reqd: 0 },     // Null / Not Mandatory
            };
        }
        
        if (fieldnames_to_be_altered) {
            Object.keys(fieldnames_to_be_altered).forEach((fieldname) => {
                let property_to_be_altered = fieldnames_to_be_altered[fieldname];
                Object.keys(property_to_be_altered).forEach((property) => {
                    let value = property_to_be_altered[property];
                    frm.fields_dict["assets"].grid.update_docfield_property(fieldname, property, value);
                });
            });
            frm.refresh_field("assets");
        }
    },
});

frappe.ui.form.on("Asset Movement Item", {
    asset: function (frm, cdt, cdn) {
        // on manual entry of an asset auto sets their source location / employee
        const asset_name = locals[cdt][cdn].asset;
        if (asset_name) {
            frappe.db
                .get_doc("Asset", asset_name)
                .then((asset_doc) => {
                    if (asset_doc.location)
                        frappe.model.set_value(cdt, cdn, "source_location", asset_doc.location);
                    if (asset_doc.custodian)
                        frappe.model.set_value(cdt, cdn, "from_employee", asset_doc.custodian);
                })
                .catch((err) => {
                    console.log(err); // eslint-disable-line
                });
        }
    },
});

frappe.ui.form.on('Asset', {
    refresh: function(frm) {
        // Only allow splitting if the asset is submitted and has a quantity greater than 1
        if (frm.doc.docstatus === 1 && frm.doc.asset_quantity > 1) {
            
            // Remove the native core split asset option under 'Manage'
            frm.page.remove_inner_button(__('Split Asset'), __('Manage'));
            
            // Add our customized option with the extra strategy field
            frm.page.add_inner_button(__('Split Asset'), function() {
                let dialog = new frappe.ui.Dialog({
                    title: __('Split Asset'),
                    fields: [
                        {
                            label: __('Current Quantity'),
                            fieldname: 'current_qty',
                            fieldtype: 'Float',
                            read_only: 1,
                            default: frm.doc.asset_quantity
                        },
                        {
                            label: __('Split Quantity'),
                            fieldname: 'split_qty',
                            fieldtype: 'Int',
                            reqd: 1,
                            description: __('The quantity you want to extract from this asset.')
                        },
                        {
                            label: __('Split Strategy'),
                            fieldname: 'split_type',
                            fieldtype: 'Select',
                            options: ['Individual', 'Grouped'],
                            default: 'Individual',
                            description: __('"Individual" creates distinct records for every item count. "Grouped" bundles the split quantity into one new draft record.')
                        }
                    ],
                    primary_action_label: __('Split'),
                    primary_action(values) {
                        if (values.split_qty >= frm.doc.asset_quantity) {
                            frappe.msgprint(__('Split quantity must be strictly less than the current asset quantity.'));
                            return;
                        }
                        if (values.split_qty <= 0) {
                            frappe.msgprint(__('Split quantity must be greater than 0.'));
                            return;
                        }
                        
                        dialog.hide();
                        
                        frappe.call({
                            // Pointing to the remapped whitelisted path handled in your hooks.py
                            method: "erpnext.assets.doctype.asset.asset.split_asset", 
                            args: {
                                asset_name: frm.doc.name,
                                split_qty: values.split_qty,
                                split_type: values.split_type
                            },
                            freeze: true,
                            freeze_message: __("Processing Asset Split..."),
                            callback: function(r) {
                                if (!r.exc) {
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                });
                dialog.show();
            }, __('Manage'));
        }
    }
});

